  "inlineSchema": "// Office Catering Platform — Prisma schema (PostgreSQL / Neon)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\nenum Role {\n  USER\n  ADMIN\n  SUPER_ADMIN\n}\n\nenum PaymentMode {\n  CASH\n  WALLET\n}\n\nenum MealSlot {\n  LUNCH\n  DINNER\n}\n\nenum OrderStatus {\n  PLACED\n  CANCELLED\n  DELIVERED\n}\n\nenum PaymentStatus {\n  UNPAID\n  PAID\n  WALLET_CHARGED\n}\n\nenum WalletTxType {\n  DEPOSIT\n  CHARGE\n  DUE_PAYMENT\n  ADJUSTMENT\n}\n\n/// Bangladesh week starts Saturday\nenum Weekday {\n  SAT\n  SUN\n  MON\n  TUE\n  WED\n  THU\n  FRI\n}\n\nmodel Account {\n  id                       String  @id @default(cuid())\n  userId                   String\n  type                     String\n  provider                 String\n  providerAccountId        String\n  refresh_token            String? @db.Text\n  access_token             String? @db.Text\n  expires_at               Int?\n  token_type               String?\n  scope                    String?\n  id_token                 String? @db.Text\n  session_state            String?\n  refresh_token_expires_in Int?\n  user                     User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\nmodel User {\n  id              String      @id @default(cuid())\n  name            String?\n  email           String?     @unique\n  emailVerified   DateTime?\n  image           String?\n  role            Role        @default(USER)\n  employeeId      String?\n  deskNumber      String?\n  buildingNumber  String?\n  floorNumber     String?\n  locationId      String?\n  paymentMode     PaymentMode @default(CASH)\n  /// Balance in integer taka; may be negative (due)\n  balance         Int         @default(0)\n  profileComplete Boolean     @default(false)\n  isBanned        Boolean     @default(false)\n  createdAt       DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  location            Location?           @relation(fields: [locationId], references: [id])\n  accounts            Account[]\n  sessions            Session[]\n  adminLocations      AdminLocation[]\n  orders              Order[]\n  walletTransactions  WalletTransaction[] @relation(\"WalletOwner\")\n  createdTransactions WalletTransaction[] @relation(\"WalletCreator\")\n\n  @@index([locationId])\n  @@index([role])\n}\n\nmodel Location {\n  id                String   @id @default(cuid())\n  name              String\n  address           String?\n  /// Default cutoff as \"HH:mm\" in Asia/Dhaka (e.g. \"11:00\")\n  defaultCutoffTime String   @default(\"11:00\")\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  users          User[]\n  adminLocations AdminLocation[]\n  dailyMenus     DailyMenu[]\n  weekdayMenus   WeekdayMenu[]\n  orders         Order[]\n}\n\nmodel AdminLocation {\n  id         String @id @default(cuid())\n  userId     String\n  locationId String\n\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  location Location @relation(fields: [locationId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, locationId])\n}\n\nmodel MealCatalog {\n  id           String   @id @default(cuid())\n  name         String\n  description  String?\n  imageUrl     String?\n  defaultPrice Int\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  dailyMenus   DailyMenu[]\n  weekdayMenus WeekdayMenu[]\n}\n\n/// Recurring meal for a weekday at one office (e.g. every Sunday lunch)\nmodel WeekdayMenu {\n  id            String   @id @default(cuid())\n  locationId    String\n  weekday       Weekday\n  slot          MealSlot\n  title         String\n  description   String?\n  price         Int\n  imageUrl      String?\n  catalogItemId String?\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  location    Location     @relation(fields: [locationId], references: [id], onDelete: Cascade)\n  catalogItem MealCatalog? @relation(fields: [catalogItemId], references: [id], onDelete: SetNull)\n\n  @@unique([locationId, weekday, slot])\n  @@index([weekday, isActive])\n}\n\nmodel DailyMenu {\n  id            String    @id @default(cuid())\n  locationId    String\n  date          DateTime  @db.Date\n  slot          MealSlot\n  title         String\n  description   String?\n  price         Int\n  imageUrl      String?\n  catalogItemId String?\n  /// Absolute cutoff datetime (Asia/Dhaka resolved); null = use location default for that day\n  cutoffAt      DateTime?\n  isPublished   Boolean   @default(false)\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  location    Location     @relation(fields: [locationId], references: [id], onDelete: Cascade)\n  catalogItem MealCatalog? @relation(fields: [catalogItemId], references: [id], onDelete: SetNull)\n  orders      Order[]\n\n  @@unique([locationId, date, slot])\n  @@index([date, isPublished])\n}\n\nmodel Order {\n  id            String        @id @default(cuid())\n  userId        String\n  dailyMenuId   String\n  locationId    String\n  amount        Int\n  note          String?\n  status        OrderStatus   @default(PLACED)\n  paymentStatus PaymentStatus @default(UNPAID)\n  deliveredAt   DateTime?\n  paidAt        DateTime?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  user      User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  dailyMenu DailyMenu           @relation(fields: [dailyMenuId], references: [id], onDelete: Cascade)\n  location  Location            @relation(fields: [locationId], references: [id], onDelete: Cascade)\n  walletTxs WalletTransaction[]\n\n  @@index([dailyMenuId, status])\n  @@index([locationId, createdAt])\n  @@index([userId, createdAt])\n}\n\nmodel WalletTransaction {\n  id           String       @id @default(cuid())\n  userId       String\n  type         WalletTxType\n  /// Signed amount applied to balance (positive deposit, negative charge)\n  amount       Int\n  balanceAfter Int\n  orderId      String?\n  createdById  String?\n  note         String?\n  createdAt    DateTime     @default(now())\n\n  user      User   @relation(\"WalletOwner\", fields: [userId], references: [id], onDelete: Cascade)\n  order     Order? @relation(fields: [orderId], references: [id], onDelete: SetNull)\n  createdBy User?  @relation(\"WalletCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n\n  @@index([userId, createdAt])\n}\n",
